      faq_g_c_sub: '\u041a\u0430\u043a \u0437\u0430\u0449\u0438\u0449\u0435\u043d\u044b \u0434\u0430\u043d\u043d\u044b\u0435, \u0447\u0442\u043e \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u043c \u0438 \u043a\u0430\u043a \u043c\u044b \u043e\u0442\u043d\u043e\u0441\u0438\u043c\u0441\u044f \u043a \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0430\u043c-\u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u0430\u043c.',
      faq_g_d: '\u041e\u0442\u0440\u0430\u0441\u043b\u0438 \u043f\u0440\u0430\u0432\u0430 \u0438 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430',
      faq_g_d_sub: '\u0414\u043b\u044f \u043a\u0430\u043a\u0438\u0445 \u043e\u0442\u0440\u0430\u0441\u043b\u0435\u0439 \u043d\u0430\u0441\u0442\u0440\u043e\u0435\u043d LexFlow \u0438 \u043a\u0430\u043a \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u043e\u0432\u0430\u043d \u043f\u0440\u0438\u0451\u043c \u0437\u0430\u044f\u0432\u043e\u043a.',
      faq_g_e: '\u0418\u043d\u0442\u0435\u0433\u0440\u0430\u0446\u0438\u0438',
